			output.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
			output.setEstimateProvenance("frontier-v2-exact-fact", "frontier_v2_exact_fact");
			output.putPlannedStringMetric("optimizer.frontierLeo.output_rows.source", "exact-fact");
			output.putPlannedDoubleMetric("optimizer.frontierLeo.output_rows.raw", rawRows);
